import json, hashlib, platform, sys
from pathlib import Path
from datetime import datetime, timezone
from collections import Counter

base=Path.cwd()
read=lambda f:json.loads(Path(f).read_text())
a=read('annotation.final.json');checks=read('checks.json');firstchecks=read('checks.first.json');review=read('review_notes.json');freeze=read('first_complete_record.json');repairs=read('repair_log.json');p=read('packet.json')
assert checks['status']=='pass',checks
assert not checks['errors']
assert Path('annotation.json').read_bytes()==Path('annotation.final.json').read_bytes()
assert hashlib.sha256(Path('annotation.first_complete.json').read_bytes()).hexdigest()==freeze['annotation_sha256']
assert hashlib.sha256(Path('packet.json').read_bytes()).hexdigest()==a['packet_sha256']==freeze['packet_sha256']

# Bookkeeping closes the audit flags produced by the final mechanical check; no new source review round occurs here.
prior={};counts=Counter()
for r in review['first_checker_flag_resolutions']:
 f=r['flag'];key=(f['code'],f['unit_id']);n=counts[key];counts[key]+=1
 prior[(key,n)]=r
counts=Counter();finalres=[]
for i,f in enumerate(checks['review_flags']):
 key=(f['code'],f['unit_id']);n=counts[key];counts[key]+=1
 if (key,n) in prior:
  previous=prior[(key,n)]
  r={k:v for k,v in previous.items() if k not in ['check_file','flag_index_zero_based','flag']}
  r.update({'check_file':'checks.json','flag_index_zero_based':i,'flag':f,'source_review_link':{'check_file':'checks.first.json','flag_index_zero_based':previous['flag_index_zero_based']}})
 else:
  assert key==('application_audit','F02-S04') and n==2
  u=next(x for x in a['units'] if x['unit_id']=='F02-S04');j=a['units'].index(u);event=u['institution']['application_evidence'][2]
  r={'check_file':'checks.json','flag_index_zero_based':i,'flag':f,'target_pointer':f'/units/{j}/institution/application_evidence/2','status':'unresolved','rationale':'This flag is generated by the explicit uncertainty record added during the single source review. The final paragraph omits the suggested backward-compatibility phrase. The core documentation action is observed, but adoption of every qualification remains unestablished.','evidence':event['evidence'],'source_review_link':{'repair_log':'repair_log.json','change_id':'R05'}}
 finalres.append(r)
review['final_checker_flag_resolutions']=finalres
review['summary']['final_flags_reviewed']=len(finalres)
review['summary']['first_checker_status']=firstchecks['status']
review['summary']['final_checker_status']=checks['status']
review['summary']['final_flag_status_counts']=dict(Counter(x['status'] for x in finalres))
review['summary']['mechanical_errors_remaining']=len(checks['errors'])
review['summary']['source_review_complete']=True
Path('review_notes.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n')
assert len(finalres)==len(checks['review_flags'])

source_files=['INSTRUCTIONS.txt','protocol/codebook.txt','protocol/annotation_schema.json','packet.json','tools/check_annotation.py']
generated_files=['build_annotation.py','annotation.json','annotation.first_complete.json','first_complete_record.json','checks.first.json','source_review.py','annotation.final.json','repair_log.json','review_notes.json','checks.json','finalize_run.py','access_record.json','run_summary.json','run_log.json','output_manifest.json']

def digest(f):return hashlib.sha256(Path(f).read_bytes()).hexdigest()

access={'run_id':'F02_v04_r3','authorized_directory':str(base),
 'configuration':{'selection':'inherited primary configuration','model_override_used':False,'exact_model_identifier':None,'provider_snapshot':None,'reasoning_effort':None,'seed':None,'sampling':None,'token_use':None,'cost':None,'configuration_basis':'The dispatch specifies inherited primary configuration without override. No provider snapshot, exact runtime model identifier, seed, sampling parameters, token accounting, or cost was exposed to this run; no identity is inferred from protocol files.'},
 'runtime':{'python_version':sys.version,'python_implementation':platform.python_implementation(),'platform':platform.system(),'shell':'bash','working_directory':str(base),'ordinary_runtime_dependencies':['Python standard library: json, pathlib, hashlib, copy, collections, datetime, platform, sys','jsonschema, imported by the supplied checker'],'runtime_documentation_read':[]},
 'files_accessed':[{'path':str(base/f),'access':'read only','purpose':('assigned source packet; read completely and used for exact Unicode anchors' if f=='packet.json' else 'assigned run instructions, coding specification, schema, or checker'),'sha256':digest(f)} for f in source_files]+[{'path':str(base/f),'access':'created within run; read where needed for checking, review, and audit bookkeeping','purpose':'generated run output or reproducible local script'} for f in generated_files],
 'directory_inventory_only':['input_manifest.json','calibration/annotation.json','calibration/packet.json','calibration/cases.json'],
 'calibration_contents_accessed':False,'input_manifest_contents_accessed':False,'external_research_sources_accessed':[],'other_run_or_parent_directory_accesses':[],'agents_spawned':False,'post_dispatch_new_sources_added':False,
 'source_preservation':'Original files were accessed only for reads. The packet hash still matches the first-complete record. Generated files reside only in the authorized run directory.',
 'access_limits':'This record enumerates directly accessed task files. Ordinary implicit Python interpreter and installed-library reads are runtime dependencies, not additional research inputs; their individual transitive files were not inventoried.'}
Path('access_record.json').write_text(json.dumps(access,ensure_ascii=False,indent=2)+'\n')

summary={'run_id':'F02_v04_r3','episode_id':'F02','packet_sha256':a['packet_sha256'],'status':'complete_with_preserved_evidence_limits','checker_status':checks['status'],
 'counts':{'screened_entries':len(a['entry_screening']),'focal_entries':len(p['selection_design']['focal_source_ids']),'supplemental_entries':len(p['entries'])-len(p['selection_design']['focal_source_ids']),'units':len(a['units']),'statement_units':sum(u['record_role']=='statement' for u in a['units']),'context_units':sum(u['record_role']=='context' for u in a['units']),'empty_entries':sum(e['disposition']=='empty' for e in a['entry_screening']),'relations':len(a['relations']),'outcomes':len(a['episode_summary']['observed_outcomes']),'mechanisms':len(a['episode_summary']['mechanisms']),'exact_anchor_references':checks['exact_anchor_references'],'first_checker_flags':len(firstchecks['review_flags']),'final_checker_flags':len(checks['review_flags']),'mechanical_errors_remaining':0,'source_review_rounds':1,'field_level_repairs':len(repairs['changes']),'meaning_changing_field_repairs':repairs['meaning_changing_changes']},
 'institutional_type_counts':dict(Counter(u['institution']['type'] for u in a['units'] if u['record_role']=='statement')),
 'material_review_change':'The empty-string suggestion\'s recorded-merge disposition was narrowed from this_proposition to broader_proposal because the final paragraph omits the explicit backward-compatibility phrase. Two changed fields describe this one substantive narrowing; other repairs clarify evidence basis or conventions.',
 'unresolved_limits':['Exact antecedents of Both are good changes and fixed remain unresolved without reliable threads.','The precise intermediate redundant star check cannot be verified from the final head patch; removal is specifically reported.','The empty-string documentation action is observed, but adoption of the omitted explicit backward-compatibility rationale is unresolved.','No supplied basis establishes rule authority, a shared institutional expectation, causal effects of review, referenced-proposal outcomes, or network adoption.'],
 'output_paths':{f:str(base/f) for f in ['annotation.final.json','annotation.first_complete.json','checks.first.json','checks.json','repair_log.json','review_notes.json','access_record.json','run_log.json','output_manifest.json']}}
Path('run_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')

stages=[
 {'stage':'input_reading','result':'All run instructions, codebook, schema, and packet read. Truncated combined outputs were recovered in bounded reads. An initial inventory script used sources instead of entries and stopped with KeyError; the actual entries were then read completely. No input was changed.'},
 {'stage':'first_complete','artifact':'annotation.first_complete.json','sha256':freeze['annotation_sha256'],'result':'Full 22-entry screening, 12-unit annotation preserved before checks and source self-review.'},
 {'stage':'first_checker','artifact':'checks.first.json','result':firstchecks['status'],'errors':len(firstchecks['errors']),'review_flags':len(firstchecks['review_flags'])},
 {'stage':'mechanical_repair','result':'No first-check mechanical errors required repair.'},
 {'stage':'source_self_review','artifact':'review_notes.json','rounds':1,'result':'Completed source-based omission, qualifier, role, evidence, authority/recognition/application, disposition/identity, level, outcome, and mechanism review. Field-level changes preserved in repair_log.json.'},
 {'stage':'final_checker','artifact':'checks.json','result':checks['status'],'errors':len(checks['errors']),'review_flags':len(checks['review_flags'])},
 {'stage':'audit_bookkeeping','result':'Every first and final checker flag has retained, corrected, or unresolved status with cited source evidence. Original first-complete hash preserved; annotation.json equals annotation.final.json.'}]
Path('run_log.json').write_text(json.dumps({'run_id':'F02_v04_r3','completed_at_utc':datetime.now(timezone.utc).isoformat(),'stages':stages,'checks_preserved':['checks.first.json','checks.json'],'all_checks_accounted_for':True,'source_review_rounds':1},ensure_ascii=False,indent=2)+'\n')
manifest={'run_id':'F02_v04_r3','packet_sha256':a['packet_sha256'],'files':[{'path':str(base/f),'bytes':Path(f).stat().st_size,'sha256':digest(f)} for f in generated_files if f!='output_manifest.json'],'manifest_excludes_its_own_hash':True}
Path('output_manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({'run_id':'F02_v04_r3','status':summary['status'],'counts':summary['counts'],'flag_resolution_counts':review['summary']['final_flag_status_counts'],'first_complete_sha256':freeze['annotation_sha256'],'final_sha256':digest('annotation.final.json'),'all_outputs_directory':str(base)},indent=2))
